"""Suggestion model for the Proactive Intelligence Engine."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import UTC, datetime
from enum import Enum
from typing import Any
from uuid import uuid4


class SuggestionPriority(str, Enum):
    """Priority assigned to a suggestion."""

    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


@dataclass(frozen=True, slots=True)
class Suggestion:
    """Represents a recommendation generated by the Kernel."""

    title: str
    reason: str
    priority: SuggestionPriority = SuggestionPriority.MEDIUM
    confidence: float = 1.0
    suggestion_id: str = field(default_factory=lambda: uuid4().hex)
    timestamp: datetime = field(default_factory=lambda: datetime.now(UTC))
    metadata: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        """Serialize the suggestion."""

        return {
            "suggestion_id": self.suggestion_id,
            "title": self.title,
            "reason": self.reason,
            "priority": self.priority.value,
            "confidence": self.confidence,
            "timestamp": self.timestamp.isoformat(),
            "metadata": self.metadata.copy(),
        }